  "task.cloth.name": {
    "en": "Dual-arm cloth",
    "zh-CN": "双臂布料操作"
  },
  "task.plug.name": {
    "en": "Peg-in-hole assembly",
    "zh-CN": "轴孔装配"
  },
  "task.pusht.name": {
    "en": "Contact-driven Push-T",
    "zh-CN": "接触驱动 Push-T"
  },
  "task.box.name": {
    "en": "Multi-object packing",
    "zh-CN": "多物体装箱"
  },
  "task.marker.name": {
    "en": "Slender-tool insertion",
    "zh-CN": "细长工具插入"
  },
  "task.rope.name": {
    "en": "Rope threading",
    "zh-CN": "绳索穿环"
  },
  "task.cloth.objective": {
    "en": "Bring opposing cloth regions together while maintaining valid grasps.",
    "zh-CN": "在保持有效抓取的同时，将布料的相对区域靠拢。"
  },
  "task.plug.objective": {
    "en": "Align a cylindrical peg with the socket and reach the required insertion depth.",
    "zh-CN": "将圆柱销与孔座对齐，并达到所需插入深度。"
  },
  "task.pusht.objective": {
    "en": "Push the T body toward its goal position and orientation.",
    "zh-CN": "将 T 形物体推向目标位置和朝向。"
  },
  "task.box.objective": {
    "en": "Place and release three objects within the open container.",
    "zh-CN": "将三个物体放入开放容器内并松开。"
  },
  "task.marker.objective": {
    "en": "Reorient the marker and guide its tip into the inclined holder.",
    "zh-CN": "调整笔状工具的朝向，引导尖端进入倾斜支座。"
  },
  "task.rope.objective": {
    "en": "Guide a grasped endpoint through the ring opening and pull a rope segment through.",
    "zh-CN": "引导抓取的绳端穿过圆环开口，并拉过一段绳索。"
  },
  "task.cloth.method": {
    "en": "Distance-constrained particles with structural, shear and bending links; two independently targeted arms.",
    "zh-CN": "使用带有结构、剪切和弯曲连接的距离约束粒子，以及两条独立设定目标的机械臂。"
  },
  "task.plug.method": {
    "en": "Rigid-body contact and a hollow socket with explicit radial and angular insertion checks.",
    "zh-CN": "基于刚体接触与中空孔座，显式检查插入时的径向和角度误差。"
  },
  "task.pusht.method": {
    "en": "A compound T rigid body, contact impulses, planar constraints and friction.",
    "zh-CN": "使用复合 T 形刚体、接触冲量、平面约束与摩擦。"
  },
  "task.box.method": {
    "en": "Rigid bodies, lock grasps, gravity, container walls and geometric containment tests.",
    "zh-CN": "使用刚体、锁定抓取、重力、容器壁与几何包含检验。"
  },
  "task.marker.method": {
    "en": "A long rigid tool, tracked tip and tilted narrow holder with orientation-sensitive contact.",
    "zh-CN": "使用细长刚性工具、尖端跟踪与倾斜窄支座，接触结果取决于工具朝向。"
  },
  "task.rope.method": {
    "en": "A particle chain with length constraints, a segmented ring collider and directed plane-crossing tests.",
    "zh-CN": "使用带长度约束的粒子链、分段圆环碰撞体与有向平面穿越检验。"
  },
  "task.cloth.limits": {
    "en": "No cloth self-collision or material calibration; fold progress is a geometric proxy.",
    "zh-CN": "未模拟布料自碰撞，也未标定材质；折叠进度只是几何代理指标。"
  },
  "task.plug.limits": {
    "en": "The socket uses a discretized collision wall; this is not a force-controlled industrial assembly model.",
    "zh-CN": "孔座采用离散碰撞壁，并非力控工业装配模型。"
  },
  "task.pusht.limits": {
    "en": "Planar motion and a heuristic feedback controller; no learned policy or optimality guarantee.",
    "zh-CN": "采用平面运动和启发式反馈控制器，不使用学习策略，也不保证最优性。"
  },
  "task.box.limits": {
    "en": "Small fixed object set; no general bin-packing optimizer.",
    "zh-CN": "仅处理固定的小规模物体集合，不包含通用装箱优化器。"
  },
  "task.marker.limits": {
    "en": "Simplified cylindrical contact geometry; no flexible-tool or tactile model.",
    "zh-CN": "采用简化的圆柱接触几何，不包含柔性工具或触觉模型。"
  },
  "task.rope.limits": {
    "en": "No knot topology or rope self-collision; ring collision is an explicit geometric approximation.",
    "zh-CN": "不处理绳结拓扑或绳索自碰撞；圆环碰撞采用显式几何近似。"
  },
